  return [{ json: { valido: true, sin_token: true, usuario_id: null, rol: null, exp: null } }];
}

const partes = cabecera.match(/^Bearer\s+([A-Za-z0-9_-]+)\.([0-9a-f]{64})$/i);
if (!partes) return rechazar(401, 'token_invalido');

let secreto = null;
try {
  secreto = $env.N8N_AUTH_SECRET || null;
} catch (e) {
  secreto = null;
}
if (!secreto) return rechazar(500, 'autenticacion_no_configurada');

// Comparacion en tiempo constante, sobre bytes del mismo largo.
const esperada = Buffer.from(crypto.createHmac('sha256', secreto).update(partes[1]).digest('hex'), 'hex');
const recibida = Buffer.from(partes[2].toLowerCase(), 'hex');
if (esperada.length !== recibida.length || !crypto.timingSafeEqual(esperada, recibida)) {
  return rechazar(401, 'token_invalido');
}

let payload;
try {
  payload = JSON.parse(Buffer.from(partes[1], 'base64url').toString('utf8'));
} catch (e) {
  return rechazar(401, 'token_invalido');
}

const expMs = Number(payload.exp);
if (!Number.isFinite(expMs) || expMs <= Date.now()) return rechazar(401, 'token_invalido');
if (!UUID.test(String(payload.id || ''))) return rechazar(401, 'token_invalido');
if (!NIVEL[payload.role]) return rechazar(401, 'token_invalido');
if (NIVEL[payload.role] < NIVEL[rolMinimo]) return rechazar(403, 'rol_no_permitido');

return [{
  json: {
    valido: true,
    sin_token: false,
    usuario_id: payload.id,
    rol: payload.role,
    exp: Math.floor(expMs / 1000),
  },
}];

// Contrato C2 2.5: 400 datos_invalidos si el estado no existe o si falta la
// cuadrilla al asignar. Las transiciones las decide la consulta, con el estado
// que tiene el operativo en ese momento.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ESTADOS = ['asignado', 'en_curso', 'cerrado'];
const cuerpo = $('Webhook Asignar Operativo').first().json.body || {};

const operativoId = String(cuerpo.operativo_id || '');
const estado = String(cuerpo.estado || '');
const crudaCuadrilla = cuerpo.cuadrilla_id;
const cuadrillaId = crudaCuadrilla === undefined || crudaCuadrilla === null || crudaCuadrilla === ''
  ? null
  : Number(crudaCuadrilla);

const cuadrillaInvalida = cuadrillaId !== null
  && (!Number.isInteger(cuadrillaId) || cuadrillaId <= 0);

if (
  !UUID.test(operativoId)
  || !ESTADOS.includes(estado)
  || cuadrillaInvalida
  // Pasar a "asignado" exige cuadrilla; en_curso y cerrado la heredan.
  || (estado === 'asignado' && cuadrillaId === null)
) {
  return [{ json: { valido: false, http_code: 400, error: 'datos_invalidos' } }];
}

return [{
  json: {
    valido: true,
    operativo_id: operativoId,
    estado,
    cuadrilla_id: cuadrillaId,
  },
}];

// Contrato C2 2.5: 404 si el operativo no existe, 400 si la cuadrilla no existe
// o no esta activa, 409 si la transicion no esta en la tabla, y 200 con el
// operativo en el formato de 2.3 cuando el cambio se aplico.
const f = $input.first().json || {};

if (!Number(f.existe)) {
  return [{
    json: {
      cerrado: false,
      http_code: 404,
      cuerpo: { error: 'operativo_no_encontrado' },
    },
  }];
}

if (!Number(f.cuadrilla_ok)) {
  return [{
    json: {
      cerrado: false,
      http_code: 400,
      cuerpo: { error: 'datos_invalidos' },
    },
  }];
}

if (!Number(f.transicion_ok)) {
  return [{
    json: {
      cerrado: false,
      http_code: 409,
      cuerpo: { error: 'transicion_invalida', estado_actual: f.estado_actual },
    },
  }];
}

const operativo = {
  id: f.id,
  zona: f.zona,
  zona_id: f.zona_id,
  estado: f.estado,
  cuadrilla: f.cuadrilla || null,
  reportes: Number(f.reportes),
  creado_en: f.creado_en,
  asignado_en: f.asignado_en || null,
  cerrado_en: f.cerrado_en || null,
};

return [{
  json: {
    cerrado: f.estado === 'cerrado',
    http_code: 200,
    cuerpo: operativo,
    operativo_id: f.id,
    zona_id: f.zona_id,
    cuadrilla_id: f.cuadrilla_id === null || f.cuadrilla_id === undefined
      ? null
      : Number(f.cuadrilla_id),
    reportes: Number(f.reportes),
    horas_atencion: f.horas_atencion === null || f.horas_atencion === undefined
      ? null
      : Number(f.horas_atencion),
  },
}];

// Sobre comun del contrato 4.7 (docs/architecture/eventos.md) para
// operativo.cerrado. horas_atencion lo calcula la consulta entre creado_en y
// cerrado_en, el mismo calculo que usara HU-11 para los KPIs.
const r = $('Armar respuesta (asignar)').first().json;

return [{
  json: {
    id: $('Generar ID operativo.cerrado').first().json.eventoId,
    tipo: 'operativo.cerrado',
    fecha: new Date().toISOString(),
    origen: 'n8n/operativos',
    datos: {
      operativo_id: r.operativo_id,
      zona_id: r.zona_id,
      cuadrilla_id: r.cuadrilla_id,
      reportes: r.reportes,
      horas_atencion: r.horas_atencion,
    },
  },
}];
